UPDATE fcc_call_session c JOIN (
SELECT #{d.callId} AS call_id, #{d.version} AS expected_version, #{d.endedAt} AS end_time, #{d.cause} AS cause, #{d.evidence} AS evidence
) d ON d.call_id = c.id SET c.result = CASE WHEN c.status IN ('NORMAL_END', 'ERROR_END') THEN COALESCE(c.result, d.cause) ELSE d.cause END, c.hangup_cause = CASE WHEN c.status IN ('NORMAL_END', 'ERROR_END') THEN COALESCE(c.hangup_cause, d.cause) ELSE d.cause END, c.status = CASE WHEN c.status IN ('NORMAL_END', 'ERROR_END') THEN c.status WHEN d.cause = 'RECOVERY_UNKNOWN' THEN 'ERROR_END' ELSE 'NORMAL_END' END, c.ended_at = COALESCE(c.ended_at, d.end_time), c.attributes = JSON_SET(COALESCE(c.attributes, JSON_OBJECT()), '$.terminal', TRUE, '$.endRepair', JSON_OBJECT('evidence', d.evidence, 'checkedAt', UTC_TIMESTAMP(3))), c.updated_at = UTC_TIMESTAMP(3), c.version = c.version + 1 WHERE c.version = d.expected_version
